'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );


// VARIABLES //

var entropy = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( entropy instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof entropy, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var v = entropy( NaN, 1.0 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = entropy( 0.0, NaN );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `sigma <= 0`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = entropy( 0.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 0.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the differential entropy of an anglit distribution', opts, function test( t ) {
	var expected;
	var sigma;
	var mu;
	var i;
	var y;

	expected = data.expected;
	mu = data.mu;
	sigma = data.sigma;
	for ( i = 0; i < expected.length; i++ ) {
		y = entropy( mu[i], sigma[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'mu: '+mu[i]+', sigma: '+sigma[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[i], 5 ), 'within tolerance. mu: '+mu[i]+'. sigma: '+sigma[i]+'. y: '+y+'. E: '+expected[i]+'.' );
		}
	}
	t.end();
});
